/**
 * productStore.js
 *
 * Async SQLite-backed product lookup — Wave 2 piloted `getProductByBarcode`
 * on ScannerScreen only (see context/research-catalog-rearchitecture.md).
 * Wave 3 expands the API to cover every remaining PRODUCT_DB consumer:
 * search, featured products, category listings/counts/hero images, company
 * products, and spotlight-eligible companies — all backed by the prebuilt
 * `products.db` (generated by scripts/build-products-sqlite.js), including
 * its precomputed score/grade and summary tables (category_counts,
 * category_hero_images, spotlight_company_ids).
 *
 * Init flow (changed 2026-07-12 — see decision-log):
 *   1. Download `products.db` from REMOTE_DB_URL straight to
 *      `${documentDirectory}SQLite/products.db` via expo-file-system —
 *      this is the path expo-sqlite's openDatabaseAsync expects by default
 *      (defaultDatabaseDirectory resolves under documentDirectory). Skipped
 *      if a copy matching DB_VERSION is already on-device.
 *   2. Open it with expo-sqlite.
 *
 * Previously this bundled the 161MB `.db` as a Metro asset via
 * `Asset.fromModule(require('../../assets/db/products.db'))`. In production
 * this consistently threw `metroRequire: Cannot find module` (confirmed via
 * Sentry + live symptoms: empty company product lists, empty category
 * browse) — bundling a file that large through Metro's require()-based
 * asset graph is fragile (see the OOM warning already on the 221MB
 * `products_generated.json` in .easignore). Runtime download sidesteps
 * Metro entirely and, as a bonus, fixes the pre-existing staleness bug
 * where a rebuilt catalog never reached devices that already had a local
 * copy — DB_VERSION forces a re-download when the catalog changes.
 *
 * Failure anywhere in init is non-fatal: getProductByBarcode falls back to
 * `null`, which callers (ScannerScreen) already treat as "not found locally"
 * and fall through to their existing OFF-miss / Product Not Found handling.
 * This file must never throw out of its exported functions.
 */
import * as SQLite from 'expo-sqlite';
import * as FileSystem from 'expo-file-system/legacy';
import { captureException } from '../utils/sentry';

// Hosted in the "Catalog" Supabase Storage bucket (public). Bump DB_VERSION
// any time you re-upload a rebuilt products.db so devices that already
// downloaded a copy pick up the new one — see scripts/upload-products-db.js.
export const REMOTE_DB_URL = 'https://huvxeaegygaeotomdqpc.supabase.co/storage/v1/object/public/Catalog/products.db';
export const DB_VERSION = '2026-07-20-1';

const DB_NAME = 'products.db';
const SQLITE_DIR = `${FileSystem.documentDirectory}SQLite`;
const DEST_PATH = `${SQLITE_DIR}/${DB_NAME}`;
const VERSION_PATH = `${SQLITE_DIR}/${DB_NAME}.version`;

// Module-level DB handle. Stays null if init hasn't run yet or failed —
// getProductByBarcode treats null as "not ready" and returns null rather
// than throwing.
let _db = null;

// Module-level cached init promise, shared across every caller (including
// implicit calls from getProductByBarcode) so the copy/open work only ever
// happens once per app session, no matter how many call sites race to use it.
let _initPromise = null;

async function ensureSqliteDirExists() {
  try {
    await FileSystem.makeDirectoryAsync(SQLITE_DIR, { intermediates: true });
  } catch (e) {
    // Already exists (or some other non-fatal race) — safe to ignore. The
    // subsequent getInfoAsync/copyAsync calls will surface any real problem.
  }
}

async function currentOnDeviceVersion() {
  const info = await FileSystem.getInfoAsync(VERSION_PATH);
  if (!info.exists) return null;
  try {
    return await FileSystem.readAsStringAsync(VERSION_PATH);
  } catch (e) {
    return null;
  }
}

async function downloadDbIfNeeded() {
  const dbInfo = await FileSystem.getInfoAsync(DEST_PATH);
  const onDeviceVersion = await currentOnDeviceVersion();
  if (dbInfo.exists && onDeviceVersion === DB_VERSION) return;

  await ensureSqliteDirExists();
  await FileSystem.downloadAsync(REMOTE_DB_URL, DEST_PATH);
  await FileSystem.writeAsStringAsync(VERSION_PATH, DB_VERSION);
}

/**
 * Idempotent — safe to call multiple times or from multiple call sites at
 * once; only does the real download/DB-open work once per app session.
 * Never rejects: on failure it reports to Sentry and resolves with the DB
 * handle left null, so getProductByBarcode degrades to "not found locally."
 */
export function initProductStore() {
  if (!_initPromise) {
    _initPromise = (async () => {
      try {
        await downloadDbIfNeeded();
        _db = await SQLite.openDatabaseAsync(DB_NAME);
      } catch (error) {
        captureException(error, { function: 'initProductStore' });
        _db = null;
      }
    })();
  }
  return _initPromise;
}

/**
 * Reshape a raw `products` table row (JSON-stringified nested columns) into
 * the same product object shape PRODUCT_DB[barcode] values have in
 * src/data/products.js — the shape scorer.js's scoreProduct() and downstream
 * screens (ProductScoreScreen) expect.
 */
function rowToProduct(row) {
  return {
    barcode: row.barcode,
    name: row.name,
    brand: row.brand,
    companyId: row.companyId,
    category: row.category,
    image: row.image,
    servingSize: row.servingSize,
    calories: row.calories,
    ingredients: row.ingredients_json ? JSON.parse(row.ingredients_json) : [],
    nutrition: row.nutrition_json ? JSON.parse(row.nutrition_json) : {},
    certifications: row.certifications_json ? JSON.parse(row.certifications_json) : [],
    flags: row.flags_json ? JSON.parse(row.flags_json) : {},
    packaging: row.packaging_json ? JSON.parse(row.packaging_json) : null,
    isOrganic: !!row.isOrganic,
    isVegan: !!row.isVegan,
    isGlutenFree: !!row.isGlutenFree,
  };
}

/**
 * Returns a product object shaped like PRODUCT_DB's values, or null if not
 * found (or if the store isn't ready / query fails — this never throws).
 */
export async function getProductByBarcode(barcode) {
  await initProductStore();
  if (!_db) return null;

  try {
    const row = await _db.getFirstAsync(
      'SELECT * FROM products WHERE barcode = ?',
      [barcode]
    );
    if (!row) return null;
    return rowToProduct(row);
  } catch (error) {
    captureException(error, { function: 'getProductByBarcode', barcode });
    return null;
  }
}

/**
 * Local name/brand/category/barcode search — mirrors the old
 * `Object.values(PRODUCT_DB).filter(name/brand.includes(q))` behavior from
 * ProductSearchScreen, but delegates the matching to SQLite's precomputed,
 * already-lowercased `search_text` column (indexed) instead of scanning the
 * whole in-memory object. Returns [] on failure/not-ready, never throws.
 */
export async function searchProductsLocal(query, limit = 6) {
  await initProductStore();
  if (!_db) return [];

  try {
    const q = String(query ?? '').toLowerCase();
    const rows = await _db.getAllAsync(
      "SELECT * FROM products WHERE search_text LIKE '%' || ? || '%' LIMIT ?",
      [q, limit]
    );
    return rows.map(rowToProduct);
  } catch (error) {
    captureException(error, { function: 'searchProductsLocal', query });
    return [];
  }
}

/**
 * Fetches products for a fixed list of barcodes (e.g. ProductSearchScreen's
 * FEATURED_BARCODES) and returns them reshaped, reordered to match the INPUT
 * barcodes array's order — SQL's `IN (...)` does not preserve order, and
 * SQLite may return matched rows in any order. Barcodes with no match are
 * skipped, same as the old `.map(bc => PRODUCT_DB[bc]).filter(Boolean)`.
 * Returns [] on failure/not-ready, never throws.
 */
export async function getFeaturedProducts(barcodes) {
  await initProductStore();
  if (!_db) return [];
  if (!Array.isArray(barcodes) || barcodes.length === 0) return [];

  try {
    const placeholders = barcodes.map(() => '?').join(',');
    const rows = await _db.getAllAsync(
      `SELECT * FROM products WHERE barcode IN (${placeholders})`,
      barcodes
    );
    const byBarcode = new Map(rows.map((row) => [row.barcode, row]));
    return barcodes
      .map((bc) => byBarcode.get(bc))
      .filter(Boolean)
      .map(rowToProduct);
  } catch (error) {
    captureException(error, { function: 'getFeaturedProducts' });
    return [];
  }
}

/**
 * Returns { product, result } pairs for a HEALTHY_CATEGORIES tile, sorted
 * best-score-first (nulls/insufficient-data last, matching the old
 * productsForCategory() + in-JS scoring behavior) — but reads the
 * precomputed `score`/`grade` columns instead of re-running scoreProduct()
 * in JS. `result` is a minimal shape ({ score, grade, insufficientData}),
 * NOT scoreProduct()'s full output.
 */
export async function getProductsByCategory(categoryTile) {
  await initProductStore();
  if (!_db) return [];
  if (!categoryTile?.productCategories?.length) return [];

  try {
    const wanted = categoryTile.productCategories.map((c) => String(c).toLowerCase());
    const placeholders = wanted.map(() => '?').join(',');
    const rows = await _db.getAllAsync(
      `SELECT * FROM products WHERE lower(category) IN (${placeholders}) ORDER BY score IS NULL, score DESC`,
      wanted
    );
    return rows.map((row) => ({
      product: rowToProduct(row),
      result: {
        score: row.score,
        grade: row.grade,
        insufficientData: !row.ingredients_json || row.ingredients_json === '[]',
      },
    }));
  } catch (error) {
    captureException(error, { function: 'getProductsByCategory', categoryId: categoryTile?.id });
    return [];
  }
}

/**
 * Returns { [category_id]: count } from the precomputed category_counts
 * summary table (one row per HEALTHY_CATEGORIES tile). Returns {} on
 * failure/not-ready, never throws.
 */
export async function getCategoryCounts() {
  await initProductStore();
  if (!_db) return {};

  try {
    const rows = await _db.getAllAsync('SELECT category_id, count FROM category_counts');
    const out = {};
    for (const row of rows) out[row.category_id] = row.count;
    return out;
  } catch (error) {
    captureException(error, { function: 'getCategoryCounts' });
    return {};
  }
}

/**
 * Returns { [category_id]: image_or_null } from the precomputed
 * category_hero_images summary table. Returns {} on failure/not-ready,
 * never throws.
 */
export async function getHeroImagesByCategory() {
  await initProductStore();
  if (!_db) return {};

  try {
    const rows = await _db.getAllAsync('SELECT category_id, image FROM category_hero_images');
    const out = {};
    for (const row of rows) out[row.category_id] = row.image ?? null;
    return out;
  } catch (error) {
    captureException(error, { function: 'getHeroImagesByCategory' });
    return {};
  }
}

/**
 * Returns all products for a given companyId, reshaped like PRODUCT_DB
 * values. Returns [] on failure/not-ready, never throws.
 */
export async function getProductsByCompany(companyId) {
  await initProductStore();
  if (!_db) return [];

  try {
    const rows = await _db.getAllAsync(
      'SELECT * FROM products WHERE companyId = ?',
      [companyId]
    );
    return rows.map(rowToProduct);
  } catch (error) {
    captureException(error, { function: 'getProductsByCompany', companyId });
    return [];
  }
}

/**
 * Returns curated (real image + resolvable companyId), grade A or B
 * products, reshaped like PRODUCT_DB values — the SQL-side replacement for
 * alternatives.js's old "scan all ~136k rows, keep the ~900 curated ones,
 * then scoreProduct() each survivor" cost. The precomputed `grade` column
 * already guarantees non-insufficient-data (insufficientData products have
 * a null grade and can't match 'A'/'B'), so no client-side scoreProduct()
 * call is needed for this path at all.
 *
 * Does NOT filter by category — callers (alternatives.js) still do that in
 * JS via normalizeCategory(), since that's regex-based string normalization
 * that isn't worth re-deriving in SQLite string functions.
 *
 * Returns [] on failure/not-ready, never throws.
 */
export async function getCuratedGradeABCandidates() {
  await initProductStore();
  if (!_db) return [];

  try {
    const rows = await _db.getAllAsync(
      `SELECT * FROM products
        WHERE image IS NOT NULL AND image != ''
          AND companyId IS NOT NULL AND companyId != ''
          AND grade IN ('A', 'B')`
    );
    return rows.map((row) => ({
      product: rowToProduct(row),
      score: row.score,
      grade: row.grade,
    }));
  } catch (error) {
    captureException(error, { function: 'getCuratedGradeABCandidates' });
    return [];
  }
}

/**
 * Returns the raw rows of the precomputed spotlight_company_ids summary
 * table — companies that are ALREADY eligible for the weekly spotlight
 * (productCount > 0 AND hasHighIssue; the SQL filter that built this table
 * has already applied that logic, callers don't need to re-check it).
 * `featuredOrder` is the index into src/utils/spotlight.js's own
 * FEATURED_ORDER array (null if the company isn't in that curated list).
 * The caller (spotlight.js) still does the weekly-rotation date math and
 * looks up full Company objects from COMPANY_DB by id.
 * Returns [] on failure/not-ready, never throws.
 */
export async function getSpotlightEligibleCompanies() {
  await initProductStore();
  if (!_db) return [];

  try {
    return await _db.getAllAsync(
      'SELECT companyId, productCount, featuredOrder, hasHighIssue FROM spotlight_company_ids'
    );
  } catch (error) {
    captureException(error, { function: 'getSpotlightEligibleCompanies' });
    return [];
  }
}
